void loop() {
  float distance = readDistanceCm();

  bool objectPresent = distance > 0 && distance <= THRESHOLD_CM;

  if (objectPresent) {

    if (!lidOpen) {
      lid.write(OPEN_ANGLE);
      lidOpen = true;
